// File: src/app/api/narrate/route.ts
// POST /api/narrate — OPTIONAL per-card agent-voice narration, served OFF the critical path.
// USER DIRECTIVE 2026-10-29 (no-fallback): narration is GENERATED by the 0G Compute Router grounded
// in the card's REAL Qloo provenance (rank/affinity/explainability). There is NO template fallback.
// /api/gift paints the grid instantly with narration:null (E-2 latency gate); the UI then upgrades
// each visible card by calling this route lazily. On ANY 0G failure this route returns an HONEST
// empty state ({ narration: null, available: false }) — NEVER a fabricated template — and the UI
// shows "narration unavailable" while the gift ranking + receipt (real Qloo data) stay rendered.
import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { narrate, NarrationUnavailableError } from "@/lib/llm/narrate";
import type { Provenance } from "@/lib/types";

export const runtime = "nodejs";

const Body = z.object({
  provenance: z.object({
    qlooSays: z.object({
      rankStatement: z.string(),
      topContributors: z.array(z.string()),
      affinityBand: z.string(),
      raw: z.unknown(),
    }),
    weChose: z.object({
      reason: z.string(),
      matchType: z.enum(["exact", "semantic"]),
    }),
  }),
});

export async function POST(req: NextRequest) {
  const parsed = Body.safeParse(await req.json().catch(() => null));
  if (!parsed.success) return NextResponse.json({ error: "INVALID_INPUT" }, { status: 400 });
  try {
    const narration = await narrate(parsed.data.provenance as Provenance);
    return NextResponse.json({ narration, available: true });
  } catch (e) {
    // Honest failure — no silent template substitution. 200 with a null/flag so the UI can degrade
    // the one card gracefully (gift grid + receipt already rendered from /api/gift's real Qloo data).
    if (e instanceof NarrationUnavailableError) {
      return NextResponse.json({ narration: null, available: false });
    }
    throw e;
  }
}
